import type { PlaybookTriggerType } from './PlaybookTriggerTypes.js';
import type { Column, TableName, TypeOf } from '@servicenow/sdk-core/db';
import type { TriggerConfig, TriggerOutputs, PlaybookTriggerInstance, ActivityDefinition, ActivityConfig, DataReference, DecisionBranch, DecisionInputs, ActivityInstance, ExtractBranchIds, LaneConfig, LaneDefinition, LaneDataReference, PlaybookBodyParams } from './PlaybookTypes.js';
import type { AnyTypedEntry, ResolveActivityOutputs, WithTableName } from './PlaybookTypeUtils.js';
import type { DecisionActivityDefinition } from './built-ins/activity-definitions/index.js';
/**
 * Helper function signatures for the playbook namespace.
 */
/**
 * Extracts the user-facing input types from a trigger type.
 * Checks the second generic (`__userInputs`) first — if it provides a custom override
 * (e.g., a discriminated union), that type is used directly. Otherwise, falls back to
 * auto-deriving a flat optional object from the first generic (`__inputs`) Column definitions.
 */
type TriggerInputsOf<T> = T extends PlaybookTriggerType<any, infer U> ? [Exclude<U, undefined>] extends [never] ? T extends PlaybookTriggerType<infer I> ? {
    [K in keyof I]?: TypeOf<I[K]>;
} : Record<string, unknown> : Exclude<U, undefined> : Record<string, unknown>;
/**
 * Extract the literal `table` name from a TriggerInputsOf<T> object so that
 * the trigger's `current` data reference can be typed against the table's
 * schema. When `table` isn't a literal string (e.g. omitted, or `string`),
 * resolves to `TableName` and falls back to an untyped record.
 */
type ExtractTableFromTriggerInputs<TInputs> = TInputs extends {
    table: infer T;
} ? T extends TableName ? T : TableName : TableName;
/**
 * Required input keys from a playbook inputs schema — columns declared with
 * `mandatory: true`. Used to make the mapper return type require these keys.
 */
type RequiredInputKeys<I> = {
    [K in keyof I]: I[K] extends {
        mandatory: true;
    } ? K : never;
}[keyof I];
type OptionalInputKeys<I> = Exclude<keyof I, RequiredInputKeys<I>>;
/**
 * The shape the trigger's playbookInputs mapper must return.
 * Required inputs are required keys, optional inputs are optional keys.
 * `parentRecord` is always accepted (dataPill or raw sysId) when the trigger
 * table differs from the playbook's parentTable — it is not a declared input
 * but is handled specially by the build plugin.
 * Values are loose (`unknown`) because the platform accepts strings, data
 * pills, and template literals universally — narrowing values further would
 * be incorrect (a string-typed pill can target an integer input at runtime).
 */
type MapperReturn<I extends Record<string, Column>> = {
    [K in RequiredInputKeys<I>]: unknown;
} & {
    [K in OptionalInputKeys<I>]?: unknown;
} & {
    parentRecord?: unknown;
};
/**
 * Creates a trigger instance.
 *
 * The `I` generic is the playbook's declared inputs schema; when this trigger
 * is constructed inside `PlaybookDefinition`'s 2nd-arg triggers callback,
 * TypeScript's contextual inference flows the expected return type
 * `PlaybookTriggerInstance<I>[]` through the array literal into this call,
 * unifying `I` here with the outer playbook's `I`. That's what gives the
 * mapper return type both left-side key autocomplete (only declared inputs)
 * and required-input enforcement.
 *
 * @param triggerType - The type of trigger (RecordCreate, RecordUpdate, etc.)
 * @param config - Trigger configuration ($id, label)
 * @param triggerInputs - Trigger-specific inputs (table, condition, etc.)
 * @param playbookInputs - Optional callback that maps playbook inputs to trigger data.
 *     The arrow receives a `trigger` parameter with a typed `current` property
 *     representing the triggering record. Return an object mapping playbook input
 *     names to `wfa.playbook.dataPill()` calls wrapping trigger.current references.
 *     When the trigger table differs from the playbook's parentTable, also include
 *     `parentRecord` here: `parentRecord: wfa.playbook.dataPill(trigger.current.record)`
 *     (dataPill) or `parentRecord: '<sys_id>'` (hardcoded).
 *
 * @example
 * ```ts
 * PlaybookTrigger(
 *     PlaybookTriggerTypes.RecordCreate,
 *     { $id: Now.ID['my_trigger'], label: 'On Incident Create' },
 *     { table: 'incident' },
 *     (trigger) => ({
 *         priority: wfa.playbook.dataPill(trigger.current.priority),
 *         summary: wfa.playbook.dataPill(trigger.current.short_description),
 *         record: wfa.playbook.dataPill(trigger.current),
 *     })
 * )
 * ```
 */
export type TriggerFunction = <T extends PlaybookTriggerType<any, any>, const TInputs extends TriggerInputsOf<T>, I extends Record<string, Column> = Record<string, never>>(triggerType: T, config: TriggerConfig, triggerInputs: TInputs, playbookInputs?: (trigger: TriggerOutputs<ExtractTableFromTriggerInputs<TInputs>>) => MapperReturn<I>) => PlaybookTriggerInstance<I>;
/**
 * Excludes special-case definitions from the generic overload.
 * Decision and Questionnaire have their own specialized overloads.
 * All other activities (including UpdateRecord, CreateNewRecord) use the generic overload
 * which supports dependent output inference via __rawOutputs.
 */
type GenericActivityDefinition = ActivityDefinition & {
    readonly __decisionDef?: never;
    readonly __questionnaireDef?: never;
};
/**
 * Helper type to ensure exact object shape - disallows excess properties.
 * Same pattern used by flow team in Action.ts for strict key validation.
 */
type Exact<T, U extends T> = U & Record<Exclude<keyof U, keyof T>, never>;
/**
 * Extract the inputs type from an activity definition.
 */
type InputsOf<D> = D extends {
    inputs?: infer I;
} ? I : {};
/**
 * Extract the experienceProperties type from an activity definition.
 */
type ExperienceOf<D> = D extends {
    experienceProperties?: infer E;
} ? E : {};
/**
 * Extract the raw outputs type from an activity definition for dependent resolution.
 * Returns `never` if the definition doesn't have __rawOutputs.
 */
type RawOutputsOf<D> = D extends {
    __rawOutputs: infer R;
} ? R : never;
/**
 * Resolve the outputs type for an activity definition.
 *
 * Priority:
 * 1. If __rawOutputs exists and contains typed entries → use ResolveActivityOutputs for dependent inference
 * 2. Otherwise, fall back to the outputs type from the definition
 * 3. If neither exists, return a generic Record<string, DataReference>
 */
type ResolvedOutputs<D, TInputs> = [
    RawOutputsOf<D>
] extends [never] ? D extends {
    outputs: infer Outputs;
} ? {
    [K in keyof Outputs]: WithTableName<Outputs[K]>;
} : Record<string, DataReference> : RawOutputsOf<D> extends Record<string, AnyTypedEntry> ? ResolveActivityOutputs<RawOutputsOf<D>, TInputs> : D extends {
    outputs: infer Outputs;
} ? {
    [K in keyof Outputs]: WithTableName<Outputs[K]>;
} : Record<string, DataReference>;
/**
 * Activity function signature with 4 parameters.
 *
 * This API enables:
 * 1. **Strict key validation** via Exact<> pattern (error on invalid keys in inputs/experienceProperties)
 * 2. **Dependent output inference** via const TInputs (e.g., tableName: 'incident' → record typed as incident)
 *
 * Exact<> only works on DIRECT parameters, not nested properties.
 * By extracting inputs and experienceProperties to separate parameters in Activity function,
 * we can apply Exact<> after TypeScript infers the literal types.
 *
 * Customer-defined activities with dependent outputs are supported automatically
 * when using ActivityDefinition() with a backing action/flow that has `dependent` outputs
 * (e.g., DocumentIdColumn({ dependent: 'tableName' })).
 */
export type ActivityFunction = {
    /**
     * Decision activity overload.
     * Returns ActivityInstance with typed branch references for use in Run.After().
     *
     * `conditionToRun` is omitted from the config because Decision activities express
     * their conditions via branches; setting `conditionToRun` on a Decision is not
     * supported by the platform.
     */
    <const B extends readonly DecisionBranch[]>(activityDefinition: DecisionActivityDefinition, config: Omit<ActivityConfig, 'conditionToRun'>, inputs: DecisionInputs<B>): ActivityInstance<ExtractBranchIds<B>>;
    /**
     * Generic activity overload - handles ALL other activities.
     *
     * Features:
     * - Strict key validation on inputs via Exact<>
     * - Strict key validation on experienceProperties via Exact<>
     * - Dependent output inference via ResolveActivityOutputs when __rawOutputs exists
     *
     * This includes UpdateRecord, CreateNewRecord, and any customer-defined activities.
     */
    <D extends GenericActivityDefinition, const TInputs extends InputsOf<D>, const TExperience extends ExperienceOf<D>>(activityDefinition: D, config: ActivityConfig, inputs?: Exact<InputsOf<D>, TInputs>, experienceProperties?: Exact<ExperienceOf<D>, TExperience>): Omit<ActivityInstance, 'outputs'> & {
        outputs: ResolvedOutputs<D, TInputs>;
    };
};
/**
 * Creates a lane definition with type inference.
 *
 * Wrapping a lane definition in `wfa.playbook.lane()` enables:
 * - **Autocomplete** on activity names in the returned lane reference
 * - **Type inference** for cross-lane activity output references
 *
 * The generic `A` is inferred from the `activities` callback's return type.
 */
export type LaneFunction = <A extends Record<string, ActivityInstance<any>>>(definition: {
    config: LaneConfig;
    activities: (params: PlaybookBodyParams) => A;
}) => LaneDefinition & LaneDataReference<A>;
/**
 * Creates a datapill reference for runtime data access.
 *
 * String references and object-like references (including table-aware record
 * references) are widened to `any` so whole-record/string pills remain
 * assignable where runtime pill values are accepted. Primitive types are
 * otherwise preserved so that e.g. a boolean input can only accept a boolean pill.
 */
type DataPillReturn<T> = T extends Record<string, unknown> ? any : [T] extends [string] ? any : T;
export type DataPillFunction = <T>(reference: T) => DataPillReturn<T>;
/**
 * Helper function signatures for the playbook sub-namespace under wfa.
 * These are exported individually and grouped under wfa.playbook in flow/index.ts.
 */
/**
 * Creates a trigger instance.
 */
export declare const PlaybookTrigger: TriggerFunction;
/**
 * Creates an activity instance.
 */
export declare const Activity: ActivityFunction;
/**
 * Creates a lane definition with type inference for activity names.
 */
export declare const Lane: LaneFunction;
/**
 * Creates a datapill reference for runtime data access.
 */
export declare const dataPill: DataPillFunction;
/**
 * Reference to the current activity being defined.
 * Use inside Activity() inputs or experience properties to create a data pill
 * referencing the current activity's own label or description at runtime.
 *
 * Only `label` and `description` are valid properties. Using this outside
 * Activity() inputs/experienceProperties produces a build error.
 *
 * @example
 * ```ts
 * const myActivity = Activity(
 *     ActivityDefinitions.Core.RecordForm,
 *     { $id: Now.ID['my_form'], label: 'Review Incident', ... },
 *     { someInput: wfa.playbook.dataPill(wfa.playbook.currentActivity.label) }
 * )
 * ```
 */
export declare const currentActivity: {
    readonly label: string;
    readonly description: string;
};
export {};
